grading.tests:
assert(typeof slugify === "function", "slugify must be defined");
assert(slugify("Hello World") === "hello-world", "basic two words");
assert(slugify("  Foo   Bar  ") === "foo-bar", "collapses whitespace runs");
assert(slugify("C++ & Go!") === "c-go", "strips symbols and trims hyphens");
assert(slugify("already-slugged") === "already-slugged", "idempotent on slugs");
assert(slugify("MiXeD CaSe 123") === "mixed-case-123", "keeps digits");
assert(slugify("") === "", "empty string");

assert(typeof fizzbuzz === "function", "fizzbuzz must be defined");
var r = fizzbuzz(15);
assert(Array.isArray(r), "returns an array");
assert(r.length === 15, "length 15");
assert(r[0] === 1, "1 stays a number");
assert(r[2] === "Fizz", "3 -> Fizz");
assert(r[4] === "Buzz", "5 -> Buzz");
assert(r[5] === "Fizz", "6 -> Fizz");
assert(r[9] === "Buzz", "10 -> Buzz");
assert(r[10] === 11, "11 stays a number");
assert(r[14] === "FizzBuzz", "15 -> FizzBuzz");
assert(fizzbuzz(0).length === 0, "n=0 gives empty array");

assert(typeof isBalanced === "function", "isBalanced must be defined");
assert(isBalanced("()") === true, "simple pair");
assert(isBalanced("([{}])") === true, "nested");
assert(isBalanced("(]") === false, "mismatched pair");
assert(isBalanced("((") === false, "unclosed");
assert(isBalanced(")(") === false, "wrong order");
assert(isBalanced("a(b)c[d]{e}") === true, "ignores other characters");
assert(isBalanced("") === true, "empty is balanced");

assert(typeof wordFreq === "function", "wordFreq must be defined");
var a = wordFreq("The cat and the dog");
assert(a["the"] === 2, "case-insensitive counting");
assert(a["cat"] === 1 && a["dog"] === 1 && a["and"] === 1, "counts each word");
var b = wordFreq("Hello, hello! WORLD...");
assert(b["hello"] === 2, "punctuation separates words");
assert(b["world"] === 1, "trailing punctuation stripped");
assert(Object.keys(wordFreq("")).length === 0, "empty string gives empty object");
assert(Object.keys(wordFreq("123 ... !!!")).length === 0, "no letters gives empty object");

assert(typeof fib === "function", "fib must be defined");
assert(JSON.stringify(fib(0)) === "[]", "n=0");
assert(JSON.stringify(fib(1)) === "[0]", "n=1");
assert(JSON.stringify(fib(2)) === "[0,1]", "n=2");
assert(JSON.stringify(fib(7)) === "[0,1,1,2,3,5,8]", "n=7");
assert(fib(20)[19] === 4181, "20th value");

assert(typeof deepGet === "function", "deepGet must be defined");
var o = { a: { b: { c: 42 } }, arr: [10, 20], z: 0 };
assert(deepGet(o, "a.b.c") === 42, "nested path");
assert(deepGet(o, "a.b.c", "fallback") === 42, "fallback unused when present");
assert(deepGet(o, "a.b.missing", "none") === "none", "fallback on missing leaf");
assert(deepGet(o, "q.r.s", null) === null, "fallback on missing root segment");
assert(deepGet(o, "arr.1") === 20, "array index segments work");
assert(deepGet(o, "z", -1) === 0, "falsy values are still found");
assert(deepGet(o, "a.b").c === 42, "intermediate object returned");
